/**
 * Get hourly tide heights for a date string "YYYY-MM-DD".
 * Falls back to empty array if date not in table.
 */
export function getTideHeightsForDate(dateStr: string): number[] {
  return TIDE_2026[dateStr] ?? []
}

/**
 * Get tide data as { hour, height }[] for a date string "YYYY-MM-DD".
 */
export function getTideDataForDate(dateStr: string): { hour: number; height: number }[] {
  const heights = getTideHeightsForDate(dateStr)
  return heights.map((height, hour) => ({ hour, height }))
}

/**
 * Legacy compat: get tide heights by month + day (assumes year 2026).
 * month = 1..12, day = 1..31
 */
export function getTideHeights2026(month: number, day: number): number[] {
  const mm = String(month).padStart(2, "0")
  const dd = String(day).padStart(2, "0")
  return getTideHeightsForDate(`2026-${mm}-${dd}`)
}

export function getTideData2026(month: number, day: number): { hour: number; height: number }[] {
  return getTideHeights2026(month, day).map((height, hour) => ({ hour, height }))
}

